15|export default async function SceneRoute({ params }: { params: Promise<{ sceneId: string }> }) {
16|  const { sceneId } = await params;
17|  const { book, scenes } = loadOzBook();
18|  const model = buildReaderModel(book, { scenes });
19|  const view = buildSceneView(model, sceneId);
20|  const chapters = model.chapters.map((chapter) => ({
21|    ch: chapter.ch,
22|    title: chapter.title,
23|    firstSceneId: chapter.scenes[0]?.id ?? "",
24|  }));
25|  // Page counts for the pager reducer: ids and numbers only, no text.
26|  const views = model.chapters.flatMap((chapter) =>
27|    chapter.scenes.map((scene) => ({ sceneId: scene.id, pages: paginateScene(scene.paragraphs).length })),
28|  );
29|  return (
30|    <div className="shell">
31|      <main className="book">
32|        <ScenePage
33|          key={sceneId}
34|          view={view}
35|          chapters={chapters}
36|          views={views}
37|          bookId={model.bookId}
38|          textVersion={model.textVersion}
39|        />
40|      </main>
41|    </div>
42|  );
