import { readFileSync } from "node:fs";
const book = JSON.parse(readFileSync("/workspace/wt-09/data/books/oz/book.json", "utf8"));
const analysis = JSON.parse(readFileSync("/workspace/wt-09/data/books/oz/analysis.json", "utf8"));
const CHARS = 68, WB = 250, LP = 17, FP = 16;
const words = (t) => t.split(/\s+/).filter(Boolean).length;
const lines = (t) => Math.max(1, Math.ceil(t.length / CHARS));
const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
let pages = 0, worst = 0, worstId = "";
const over = [];
for (const s of analysis.scenes) {
  const paras = [];
  for (let n = s.start_n; n <= s.end_n; n++) paras.push(byN.get(n));
  // mirror paginateScene
  const out = []; let cur = [], w = 0, l = 0;
  const flush = () => { if (!cur.length) return; out.push({ cur, w, l }); cur = []; w = 0; l = 0; };
  for (const p of paras) {
    const pw = words(p.text), pl = lines(p.text);
    const b = out.length === 0 ? FP : LP;
    if (cur.length && (w + pw > WB || l + pl > b)) flush();
    cur.push(p); w += pw; l += pl;
  }
  flush();
  pages += out.length;
  out.forEach((pg, i) => {
    const b = i === 0 ? FP : LP;
    if (pg.l > worst) { worst = pg.l; worstId = `${s.id} page${i}`; }
    if (pg.l > b || pg.w > WB) over.push(`${s.id} page${i}: ${pg.l} lines (budget ${b}) ${pg.w} words`);
  });
}
console.log(`scenes=${analysis.scenes.length} pages=${pages} worst=${worst} at ${worstId}`);
console.log(over.length ? `OVER:\n${over.join("\n")}` : "all pages within budget");
